import{_ as e,c as n,o as i,a0 as t}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Werkbladen voor mentale speloefeningen","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/nl/exercise-worksheets.md","filePath":"public/downloads/nl/exercise-worksheets.md"}');const _=e({name:"public/downloads/nl/exercise-worksheets.md"},[["render",function(e,r,_,a,o,l){return i(),n("div",null,[...r[0]||(r[0]=[t('<h1 id="werkbladen-voor-mentale-speloefeningen" tabindex="-1">Werkbladen voor mentale speloefeningen <a class="header-anchor" href="#werkbladen-voor-mentale-speloefeningen" aria-label="Permalink to &quot;Werkbladen voor mentale speloefeningen&quot;">​</a></h1><p><strong>Pétanque Academie - Praktische oefeningen</strong></p><hr><h2 id="oefening-1-reflectie-in-een-flowtoestand" tabindex="-1">Oefening 1: Reflectie in een flowtoestand <a class="header-anchor" href="#oefening-1-reflectie-in-een-flowtoestand" aria-label="Permalink to &quot;Oefening 1: Reflectie in een flowtoestand&quot;">​</a></h2><h3 id="wanneer-heb-je-een-flow-ervaring-gehad" tabindex="-1">Wanneer heb je een flow-ervaring gehad? <a class="header-anchor" href="#wanneer-heb-je-een-flow-ervaring-gehad" aria-label="Permalink to &quot;Wanneer heb je een flow-ervaring gehad?&quot;">​</a></h3><p>Denk terug aan een moment waarop je je beste pétanque ooit speelde:</p><p><strong>Beschrijf de situatie:</strong></p><ul><li>Om welk toernooi/welke wedstrijd ging het?</li><li>Wat waren de omstandigheden?</li><li>Met wie speelde je?</li></ul><hr><hr><p><strong>Hoe voelde het?</strong></p><ul><li>Hoe was je mentale toestand?</li><li>Hoe voelde de tijd aan?</li><li>Wat dacht je (of wat dacht je juist niet)?</li></ul><hr><hr><p><strong>Wat heeft je geholpen om daar te komen?</strong></p><ul><li>Wat deed je voor de wedstrijd?</li><li>Wat was er anders aan die dag?</li><li>Kun je een van die omstandigheden nabootsen?</li></ul><hr><hr><hr><h2 id="oefening-2-inventarisatie-van-je-innerlijke-criticus" tabindex="-1">Oefening 2: Inventarisatie van je innerlijke criticus <a class="header-anchor" href="#oefening-2-inventarisatie-van-je-innerlijke-criticus" aria-label="Permalink to &quot;Oefening 2: Inventarisatie van je innerlijke criticus&quot;">​</a></h2><h3 id="identificeer-je-innerlijke-criticus" tabindex="-1">Identificeer je innerlijke criticus <a class="header-anchor" href="#identificeer-je-innerlijke-criticus" aria-label="Permalink to &quot;Identificeer je innerlijke criticus&quot;">​</a></h3><p><strong>Wat zegt jouw innerlijke criticus?</strong></p><p>Noem 3-5 veelvoorkomende kritische gedachten die je hebt tijdens een wedstrijd:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Wanneer verschijnt het?</strong></p><ul><li>Na fouten? □</li><li>Voor belangrijke opnames? □</li><li>Wanneer je tegen sterke tegenstanders speelt? □</li><li>Kijken je teamgenoten mee? □</li><li>Ander: _______________________________________________</li></ul><hr><h2 id="oefening-3-herkadering-van-de-praktijk" tabindex="-1">Oefening 3: Herkadering van de praktijk <a class="header-anchor" href="#oefening-3-herkadering-van-de-praktijk" aria-label="Permalink to &quot;Oefening 3: Herkadering van de praktijk&quot;">​</a></h2><h3 id="transformeer-criticus-in-coach" tabindex="-1">Transformeer criticus in coach. <a class="header-anchor" href="#transformeer-criticus-in-coach" aria-label="Permalink to &quot;Transformeer criticus in coach.&quot;">​</a></h3><p><strong>Schrijf voor elke gedachte van je innerlijke criticus een herformulering op die je innerlijke coach kan gebruiken:</strong></p><table tabindex="0"><thead><tr><th>Innerlijke criticus</th><th>Innerlijke coach</th></tr></thead><tbody><tr><td>Voorbeeld: &quot;Ik maak altijd fouten onder druk&quot;</td><td>&quot;Ik heb eerder onder druk succes gehad, ik kan het opnieuw&quot;</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Oefen met het hardop uitspreken van deze zinnen.</strong></p><hr><h2 id="oefening-4-ontwerp-van-een-voorbereidingsroutine" tabindex="-1">Oefening 4: Ontwerp van een voorbereidingsroutine <a class="header-anchor" href="#oefening-4-ontwerp-van-een-voorbereidingsroutine" aria-label="Permalink to &quot;Oefening 4: Ontwerp van een voorbereidingsroutine&quot;">​</a></h2><h3 id="stel-je-persoonlijke-routine-samen" tabindex="-1">Stel je persoonlijke routine samen. <a class="header-anchor" href="#stel-je-persoonlijke-routine-samen" aria-label="Permalink to &quot;Stel je persoonlijke routine samen.&quot;">​</a></h3><p>Ontwerp een voorbereidingsroutine van 4 stappen die voor jou werkt:</p><p><strong>Stap 1: Visualiseer</strong></p><ul><li>Wat ga je precies visualiseren?</li><li>Hoe lang (2-3 seconden)?</li></ul><hr><p><strong>Stap 2: Ademhalen</strong></p><ul><li>Eén keer diep ademhalen of drie keer?</li><li>Is er een specifiek patroon te herkennen?</li></ul><hr><p><strong>Stap 3: Verankeren</strong></p><ul><li>Welk fysiek ankerpunt ga je gebruiken?</li><li>Aanraken van de boule? Specifieke houding?</li></ul><hr><p><strong>Stap 4: Uitvoeren</strong></p><ul><li>Wat is je mentale aanwijzing?</li><li>&quot;Vertrouwen&quot; / &quot;Meegaan&quot; / &quot;Doorgaan&quot;?</li></ul><hr><p><strong>Oefen deze routine vandaag 10 keer</strong></p><hr><h2 id="oefening-5-druktriggers" tabindex="-1">Oefening 5: Druktriggers <a class="header-anchor" href="#oefening-5-druktriggers" aria-label="Permalink to &quot;Oefening 5: Druktriggers&quot;">​</a></h2><h3 id="identificeer-uw-drukpunten" tabindex="-1">Identificeer uw drukpunten <a class="header-anchor" href="#identificeer-uw-drukpunten" aria-label="Permalink to &quot;Identificeer uw drukpunten&quot;">​</a></h3><p><strong>Welke situaties bezorgen je stress?</strong></p><p>Geef elk een cijfer van 1 (geen druk) tot 10 (extreme druk):</p><ul><li>Spelen tegen sterke tegenstanders: ___/10</li><li>Belangrijke toernooiwedstrijden: ___/10</li><li>Gelijkspel, laatste schot: ___/10</li><li>Na het maken van een fout: ___/10</li><li>Als teamgenoten toekijken: ___/10</li><li>Als ik slecht speel: ___/10</li><li>Overig: _________________________ ___/10</li></ul><p><strong>Voor uw best beoordeelde trigger:</strong></p><p>Welke fysieke sensaties merk je op?</p><hr><p>Welke gedachten komen op?</p><hr><p>Welke techniek ga je gebruiken?</p><ul><li>[ ] 3-ademhaling reset</li><li>[ ] Voorbereidingsroutine</li><li>[ ] Herformulering</li><li>[ ] Ander: _____________________</li></ul><hr><h2 id="oefening-6-oefening-in-het-wisselen-van-modus" tabindex="-1">Oefening 6: Oefening in het wisselen van modus <a class="header-anchor" href="#oefening-6-oefening-in-het-wisselen-van-modus" aria-label="Permalink to &quot;Oefening 6: Oefening in het wisselen van modus&quot;">​</a></h2><h3 id="planning-versus-uitvoering" tabindex="-1">Planning versus uitvoering <a class="header-anchor" href="#planning-versus-uitvoering" aria-label="Permalink to &quot;Planning versus uitvoering&quot;">​</a></h3><p><strong>Oefen de omschakeling:</strong></p><p><strong>Planningsfase (Vooropname):</strong></p><ul><li>Wat moet ik analyseren?</li><li>Wat is mijn strategie?</li><li>Welke foto zal ik kiezen?</li></ul><p><strong>Uitvoeringsfase (tijdens de opname):</strong></p><ul><li>Maak je hoofd leeg.</li><li>Vertrouw op je lichaam.</li><li>Laat het gebeuren</li></ul><p><strong>Oefening:</strong></p><p>Neem 5 oefenschoten. Voor elk schot:</p><ol><li>Neem 10 seconden de tijd om te plannen (analyseren, beslissen).</li><li>Neem 3 keer diep adem om van modus te wisselen.</li><li>Uitvoeren in flow-modus (zonder na te denken)</li></ol><p><strong>Reflectie:</strong></p><ul><li>Kon je het verschil tussen de modi voelen?</li><li>Was de schakelaar duidelijk?</li><li>Welke modus vind je moeilijker?</li></ul><hr><hr><hr><h2 id="oefening-7-wekelijks-oefenplan" tabindex="-1">Oefening 7: Wekelijks oefenplan <a class="header-anchor" href="#oefening-7-wekelijks-oefenplan" aria-label="Permalink to &quot;Oefening 7: Wekelijks oefenplan&quot;">​</a></h2><h3 id="focus-van-deze-week" tabindex="-1">Focus van deze week <a class="header-anchor" href="#focus-van-deze-week" aria-label="Permalink to &quot;Focus van deze week&quot;">​</a></h3><p><strong>Kies ÉÉN techniek om te oefenen:</strong></p><ul><li>[ ] 3-ademhalingen reset na elke fout</li><li>[ ] Voorbereidingsroutine bij elke worp</li><li>[ ] Herformuleer één gedachte van de innerlijke criticus per sessie</li><li>[ ] Schakelen tussen oefenmodi</li></ul><p><strong>Dagelijkse oefening:</strong></p><table tabindex="0"><thead><tr><th>Dag</th><th>Oefening</th><th>Duur</th><th>Opmerkingen</th></tr></thead><tbody><tr><td>Ma</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>di</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Wo</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Do</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Vr</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Za</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Zon</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="oefening-8-voortgang-bijhouden" tabindex="-1">Oefening 8: Voortgang bijhouden <a class="header-anchor" href="#oefening-8-voortgang-bijhouden" aria-label="Permalink to &quot;Oefening 8: Voortgang bijhouden&quot;">​</a></h2><h3 id="reflectie-aan-het-einde-van-de-week" tabindex="-1">Reflectie aan het einde van de week <a class="header-anchor" href="#reflectie-aan-het-einde-van-de-week" aria-label="Permalink to &quot;Reflectie aan het einde van de week&quot;">​</a></h3><p><strong>Wat heb je deze week geoefend?</strong></p><hr><p><strong>Wat viel je op?</strong></p><hr><hr><p><strong>Wat werkte goed?</strong></p><hr><hr><p><strong>Wat was lastig?</strong></p><hr><hr><p><strong>Waar ga je volgende week mee verder?</strong></p><hr><hr><p><strong>Wat ga je aanpassen?</strong></p><hr><hr><hr><h2 id="volgende-stappen" tabindex="-1">Volgende stappen <a class="header-anchor" href="#volgende-stappen" aria-label="Permalink to &quot;Volgende stappen&quot;">​</a></h2><h3 id="ga-door-met-je-ontwikkeling" tabindex="-1">Ga door met je ontwikkeling <a class="header-anchor" href="#ga-door-met-je-ontwikkeling" aria-label="Permalink to &quot;Ga door met je ontwikkeling&quot;">​</a></h3><p><strong>Bronnen op carreau.app:</strong></p><ul><li>Doelsjabloon - Structureer uw langetermijnontwikkeling</li><li>Dagboeksjabloon - Houd je dagelijkse voortgang bij</li><li>De Zone - Een diepgaande verkenning van flowtoestanden</li><li>Mentale kracht - Geavanceerd omgaan met druk</li></ul><p><strong>Blijf oefenen:</strong></p><ul><li>Mentale vaardigheden vereisen voortdurende training.</li><li>Begin klein, bouw geleidelijk op</li><li>Volg je voortgang</li><li>Vier de verbeteringen</li></ul><hr><p><em>Pétanque Academie - Ontwikkeling van elitespelers</em><em>carreau.app</em></p>',113)])])}]]);export{r as __pageData,_ as default};
